package org.walkwithgod.messaging;import jakarta.persistence.*;import org.walkwithgod.common.BaseEntity;import org.walkwithgod.user.AppUser;import java.util.*;
@Entity @Table(name="conversations")public class Conversation extends BaseEntity{@ManyToMany(fetch=FetchType.EAGER)@JoinTable(name="conversation_participants",joinColumns=@JoinColumn(name="conversation_id"),inverseJoinColumns=@JoinColumn(name="user_id"))private Set<AppUser> participants=new HashSet<>();@Column(length=500)private String title;public Set<AppUser> getParticipants(){return participants;}public String getTitle(){return title;}public void setTitle(String v){title=v;}}
